  "resources": ["ECR repository: example-api", "AWS account: 012345678901_1", "AWS region: us-east-1"],
  "draft_policy": {"rules":[{"rulePriority":1,"description":"keep newest 10","selection":{"tagStatus":"any","countType":"imageCountMoreThan","countNumber":10},"action":{"type":"expire"}}]},
